/**
 * pdfcn-svelte Theme System — Type Definitions
 *
 * Defines the complete type hierarchy for the pdfcn-svelte PDF theme system.
 * All PDF components consume these tokens instead of hardcoding style values.
 *
 * Architecture:
 * - PrimitiveTokens: Raw design scales (typography, spacing, weights, line heights)
 * - ColorTokens: Semantic color mappings (foreground/background pairs)
 * - TypographyTokens: Font family, size, weight, and line height decisions
 * - SpacingTokens: Page margins, section/paragraph/component gaps
 * - PageTokens: Default page size and orientation
 * - PdfcnTheme: The complete theme object combining all token layers
 */

// ─── Primitive Tokens ───────────────────────────────────────────────────────
// Raw design scales. These define WHAT values are available.
// Themes choose from these when populating semantic tokens.

/** Typography scale using a Major Third (1.25) ratio with 12pt base */
export interface TypographyScale {
	/** 10pt — Captions, footnotes */
	xs: number;
	/** 12pt — Body text (PDF standard) */
	sm: number;
	/** 15pt — Large body, small headings */
	base: number;
	/** 18pt — H4 equivalent */
	lg: number;
	/** 22pt — H3 equivalent */
	xl: number;
	/** 28pt — H2 equivalent */
	'2xl': number;
	/** 36pt — H1 equivalent */
	'3xl': number;
}

/** Spacing scale based on a 4pt grid system */
export interface SpacingScale {
	/** 0pt */
	0: number;
	/** 2pt */
	0.5: number;
	/** 4pt */
	1: number;
	/** 8pt */
	2: number;
	/** 12pt */
	3: number;
	/** 16pt */
	4: number;
	/** 20pt */
	5: number;
	/** 24pt */
	6: number;
	/** 32pt */
	8: number;
	/** 40pt */
	10: number;
	/** 48pt */
	12: number;
	/** 64pt */
	16: number;
}

/** Font weight scale */
export interface FontWeights {
	regular: number;
	medium: number;
	semibold: number;
	bold: number;
}

/** Line height scale */
export interface LineHeights {
	/** 1.2 — Tight, for headings */
	tight: number;
	/** 1.4 — Normal, for body text */
	normal: number;
	/** 1.6 — Relaxed, for reading-heavy content */
	relaxed: number;
}

/** Border radius scale for rounded corners */
export interface BorderRadiusScale {
	/** 0pt — Sharp corners */
	none: number;
	/** 2pt — Subtle rounding */
	sm: number;
	/** 4pt — Standard rounding */
	md: number;
	/** 8pt — Pronounced rounding */
	lg: number;
	/** 9999pt — Pill/circle shape */
	full: number;
}

/** Letter spacing scale for typography adjustments */
export interface LetterSpacingScale {
	/** -0.025em — Tighter spacing */
	tight: number;
	/** 0em — Normal spacing */
	normal: number;
	/** 0.025em — Slightly wider spacing */
	wide: number;
	/** 0.05em — Much wider spacing (for uppercase) */
	wider: number;
}

/** Raw design scales shared across themes */
export interface PrimitiveTokens {
	typography: TypographyScale;
	spacing: SpacingScale;
	fontWeights: FontWeights;
	lineHeights: LineHeights;
	borderRadius: BorderRadiusScale;
	letterSpacing: LetterSpacingScale;
}

// ─── Semantic Tokens ────────────────────────────────────────────────────────
// These map primitives to design intent. Themes differ primarily here.

/**
 * Semantic color tokens using the foreground/background pair convention.
 * All values must be hex strings (e.g., '#1a1a1a').
 * Forme supports hex, rgb(), and hsl() — but NOT oklch.
 */
export interface ColorTokens {
	/** Primary text and content color */
	foreground: string;
	/** Page background color */
	background: string;
	/** Subtle background for secondary areas (e.g., code blocks, table headers) */
	muted: string;
	/** Text on muted backgrounds (captions, footnotes, timestamps) */
	mutedForeground: string;
	/** Brand/accent color for emphasis and highlights */
	primary: string;
	/** Text on primary-colored backgrounds */
	primaryForeground: string;
	/** Table borders, dividers, rules */
	border: string;
	/** Secondary accent for call-to-action elements, badges */
	accent: string;
	/** Error text, warning indicators */
	destructive: string;
	/** Success states (e.g., badges, confirmations) */
	success: string;
	/** Warning states (e.g., badges, alerts) */
	warning: string;
	/** Info states (e.g., badges, informational alerts) */
	info: string;
}

/** Typography semantic tokens — what fonts and sizes to use where */
export interface TypographyTokens {
	/** Body text settings */
	body: {
		/** Font family for body text (e.g., 'Helvetica') */
		fontFamily: string;
		/** Base font size in points */
		fontSize: number;
		/** Line height multiplier */
		lineHeight: number;
	};
	/** Heading text settings */
	heading: {
		/** Font family for headings (e.g., 'Times-Roman', 'Courier') */
		fontFamily: string;
		/** Font weight as numeric value (400–700) */
		fontWeight: number;
		/** Line height multiplier for headings */
		lineHeight: number;
		/** Font sizes for each heading level in points */
		fontSize: {
			h1: number;
			h2: number;
			h3: number;
			h4: number;
			h5: number;
			h6: number;
		};
	};
}

/** Spacing semantic tokens — consistent spacing across the document */
export interface SpacingTokens {
	/** Page margin settings in points */
	page: {
		marginTop: number;
		marginRight: number;
		marginBottom: number;
		marginLeft: number;
	};
	/** Space between major document sections (after h2, before new sections) */
	sectionGap: number;
	/** Space between paragraphs and after text blocks */
	paragraphGap: number;
	/** Space between inline components, list items, table rows */
	componentGap: number;
}

/** Page layout defaults */
export interface PageTokens {
	/** Default page size */
	size: 'A4' | 'LETTER' | 'LEGAL';
	/** Default page orientation */
	orientation: 'portrait' | 'landscape';
}

// ─── Full Theme ─────────────────────────────────────────────────────────────

/**
 * The complete pdfcn-svelte theme object.
 *
 * Components read this via `usePdfcnTheme()` (Svelte context provided by
 * `PdfcnThemeProvider`) and use its tokens for all style values.
 *
 * @example
 * ```svelte
 * <PdfcnThemeProvider theme={vividTheme}>
 *   <Document>...</Document>
 * </PdfcnThemeProvider>
 * ```
 */
export interface PdfcnTheme {
	/** Theme name identifier */
	name: string;
	/** Raw design scales */
	primitives: PrimitiveTokens;
	/** Semantic color mappings */
	colors: ColorTokens;
	/** Typography settings for body and headings */
	typography: TypographyTokens;
	/** Spacing settings for page, sections, and components */
	spacing: SpacingTokens;
	/** Page layout defaults */
	page: PageTokens;
}

/** A request resolved before rendering, so renderer and browser never discard request options. */
export interface ImageRequest {
 uri: string;
 method?: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
 headers?: Record<string, string>;
 body?: string;
}

/** Fetch a PNG/JPEG and return a portable data URI. Run on the server for private credentials. */
export async function loadImage(source: string | ImageRequest): Promise<string> {
 const request: ImageRequest = typeof source === 'string' ? { uri: source } : source;
 if (!request || typeof request.uri !== 'string' || !request.uri.trim()) throw new TypeError('[loadImage] Provide an image URL in uri.');
 const unknown = Object.keys(request).filter(key => !['uri', 'method', 'headers', 'body'].includes(key));
 if (unknown.length) throw new TypeError(`[loadImage] Unsupported request options: ${unknown.join(', ')}.`);
 const method = request.method ?? 'GET';
 if (!['GET', 'POST', 'PUT', 'PATCH', 'DELETE'].includes(method)) throw new TypeError('[loadImage] method must retrieve image bytes; HEAD is not supported.');
 if (method === 'GET' && request.body !== undefined) throw new TypeError('[loadImage] GET cannot have a body. Use POST or remove body.');
 let response: Response;
 try { response = await fetch(request.uri, { method, headers: request.headers, body: request.body }); }
 catch (cause) { throw new Error('[loadImage] Image request failed. Check URL, network access, and request options.', { cause }); }
 if (!response.ok) throw new Error(`[loadImage] Image request failed with HTTP ${response.status}.`);
 const bytes = new Uint8Array(await response.arrayBuffer());
 return imageDataUri(bytes);
}

/** Validate portable image structure before an engine can silently omit corrupt bytes. */
export function imageDataUri(bytes: Uint8Array): string {
 const png = bytes.length >= 8 && [137,80,78,71,13,10,26,10].every((value, index) => bytes[index] === value);
 let mime: string;
 if (png) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let offset = 8, ended = false, hasData = false, first = true;
  while (offset + 12 <= bytes.length) {
   const length = view.getUint32(offset), end = offset + 12 + length;
   if (end > bytes.length) throw new Error('[Image] PNG contains a truncated chunk.');
   const type = String.fromCharCode(...bytes.subarray(offset + 4, offset + 8));
   if (first && (type !== 'IHDR' || length !== 13 || view.getUint32(offset + 8) === 0 || view.getUint32(offset + 12) === 0)) throw new Error('[Image] PNG has an invalid IHDR header.');
   let crc = 0xffffffff;
   for (const byte of bytes.subarray(offset + 4, offset + 8 + length)) { crc ^= byte; for (let bit = 0; bit < 8; bit++) crc = (crc >>> 1) ^ ((crc & 1) ? 0xedb88320 : 0); }
   if (((crc ^ 0xffffffff) >>> 0) !== view.getUint32(offset + 8 + length)) throw new Error(`[Image] PNG ${type} checksum is invalid.`);
   if (type === 'IDAT' && length > 0) hasData = true;
   offset = end; first = false;
   if (type === 'IEND') { ended = length === 0; break; }
  }
  if (!ended || !hasData || offset !== bytes.length) throw new Error('[Image] PNG requires complete image data and an IEND chunk.');
  mime = 'image/png';
 } else if (bytes.length >= 4 && bytes[0] === 255 && bytes[1] === 216) {
  if (bytes.at(-2) !== 255 || bytes.at(-1) !== 217) throw new Error('[Image] JPEG is truncated (missing end marker).');
  let offset = 2, frame = false, scan = false;
  while (offset + 3 < bytes.length) {
   if (bytes[offset++] !== 255) throw new Error('[Image] JPEG contains an invalid segment.');
   while (bytes[offset] === 255) offset++;
   const marker = bytes[offset++];
   if (marker === 217) break;
   const length = bytes[offset] * 256 + bytes[offset + 1];
   if (length < 2 || offset + length > bytes.length) throw new Error('[Image] JPEG contains a truncated segment.');
   if ([192,193,194].includes(marker)) { if (length < 8 || bytes[offset + 3] * 256 + bytes[offset + 4] === 0 || bytes[offset + 5] * 256 + bytes[offset + 6] === 0) throw new Error('[Image] JPEG dimensions are invalid.'); frame = true; }
   if (marker === 218) { scan = offset + length < bytes.length - 2; break; }
   offset += length;
  }
  if (!frame || !scan) throw new Error('[Image] JPEG requires a supported frame and image scan.');
  mime = 'image/jpeg';
 } else throw new Error('[Image] Expected PNG or JPEG image bytes. Convert other formats before rendering.');
 let binary = '';
 for (let i = 0; i < bytes.length; i += 8192) binary += String.fromCharCode(...bytes.subarray(i, i + 8192));
 return `data:${mime};base64,${btoa(binary)}`;
}

/** Forme does not report failed image loads, so require validated, resolved data. */
export function validateImageSource(source: unknown): string {
 if (typeof source !== 'string') throw new TypeError('[Image] src must be a PNG/JPEG data URI string. Resolve requests with loadImage before rendering.');
 const match = /^data:image\/(png|jpeg);base64,([A-Za-z0-9+/=\s]+)$/.exec(source);
 if (!match) throw new Error('[Image] Provide a PNG/JPEG data URI. Resolve URLs with await loadImage(url); convert local file bytes with imageDataUri(bytes) before rendering.');
 let binary: string;
 try { binary = atob(match[2]); } catch { throw new Error('[Image] Invalid base64 image data.'); }
 return imageDataUri(Uint8Array.from(binary, character => character.charCodeAt(0)));
}

/** Amounts are supplied by the caller; this helper only formats them. */
export interface InvoiceFormatOptions {
	/** ISO 4217 currency code. @default 'USD' */
	currency?: string;
	/** Intl locale. @default 'en-US' (matches the shipped invoice samples) */
	locale?: string;
	/** Label for the supplied tax amount. @default 'Tax' */
	taxLabel?: string;
}

export function invoiceFormatter(options: InvoiceFormatOptions): (amount: number) => string {
	const formatter = new Intl.NumberFormat(options.locale ?? 'en-US', {
		style: 'currency', currency: options.currency ?? 'USD'
	});
	return (amount) => {
		if (!Number.isFinite(amount)) throw new Error('Invoice amounts must be finite numbers. Supply calculated totals and line amounts; NaN and Infinity cannot be printed as money.');
		return formatter.format(amount);
	};
}

import type { ColorTokens } from '$lib/types/pdf-themes';

/** Theme color token keys that can be used for the color prop */
export const THEME_COLOR_KEYS = [
	'foreground',
	'background',
	'muted',
	'mutedForeground',
	'primary',
	'primaryForeground',
	'border',
	'accent',
	'destructive',
	'success',
	'warning',
	'info'
] as const satisfies (keyof ColorTokens)[];

/** Resolves a color value: theme token key → hex, or raw CSS color as-is. */
export const resolveColor = (value: string, colors: ColorTokens): string => {
	const key = value as (typeof THEME_COLOR_KEYS)[number];
	return THEME_COLOR_KEYS.includes(key) ? colors[key] : value;
};
